```sql
CREATE TABLE users (
    id          SERIAL PRIMARY KEY,          -- auto-increment (PostgreSQL)
    -- id       INT AUTO_INCREMENT PRIMARY KEY,  -- MySQL
    username    VARCHAR(50)  NOT NULL UNIQUE,
    email       VARCHAR(255) NOT NULL UNIQUE,
    password    VARCHAR(255) NOT NULL,
    age         INT          CHECK (age >= 0 AND age <= 150),
    role        VARCHAR(20)  NOT NULL DEFAULT 'user',
    is_active   BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE posts (
    id          SERIAL PRIMARY KEY,
    user_id     INT     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    title       VARCHAR(200) NOT NULL,
    content     TEXT,
    published   BOOLEAN      DEFAULT FALSE
);

-- Many-to-many junction table
CREATE TABLE post_tags (
    post_id INT REFERENCES posts(id) ON DELETE CASCADE,
    tag_id  INT REFERENCES tags(id)  ON DELETE CASCADE,
    PRIMARY KEY (post_id, tag_id)
);

-- ALTER TABLE
ALTER TABLE users ADD COLUMN phone VARCHAR(20);
ALTER TABLE users DROP COLUMN phone;
ALTER TABLE users RENAME COLUMN username TO user_name;
ALTER TABLE users ADD CONSTRAINT chk_age CHECK (age >= 18);

DROP TABLE IF EXISTS temp_table;
```

```sql
-- Basic SELECT
SELECT id, username, email FROM users;
SELECT * FROM users;

-- Aliases
SELECT username AS name,
       age * 12 AS months_old
FROM users;

-- WHERE conditions
SELECT * FROM users
WHERE age > 18
  AND role = 'admin'
  AND is_active = TRUE;

SELECT * FROM users WHERE age BETWEEN 18 AND 65;
SELECT * FROM users WHERE role IN ('admin', 'moderator');
SELECT * FROM users WHERE email LIKE '%@gmail.com';
SELECT * FROM users WHERE email ILIKE '%@gmail%';  -- case-insensitive
SELECT * FROM users WHERE phone IS NULL;

-- ORDER BY and LIMIT (pagination)
SELECT * FROM users ORDER BY age DESC, username ASC;
SELECT * FROM users ORDER BY id LIMIT 10 OFFSET 20;  -- page 3 with 10/page

-- CASE expression
SELECT username,
    CASE
        WHEN age < 18 THEN 'minor'
        WHEN age < 65 THEN 'adult'
        ELSE 'senior'
    END AS age_group
FROM users;

-- Aggregate functions
SELECT COUNT(*), COUNT(phone), SUM(salary), AVG(age), MIN(age), MAX(age)
FROM users;

-- GROUP BY and HAVING
SELECT role, COUNT(*) AS cnt, AVG(age) AS avg_age
FROM users
GROUP BY role
HAVING COUNT(*) > 5
ORDER BY cnt DESC;
```

