-- ACID Transaction
BEGIN;

UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;

COMMIT;
-- or ROLLBACK to undo everything

-- Savepoints
BEGIN;
UPDATE users SET role = 'admin' WHERE id = 5;
SAVEPOINT my_savepoint;
UPDATE users SET role = 'superadmin' WHERE id = 5;
ROLLBACK TO SAVEPOINT my_savepoint;  -- undo last update only
COMMIT;

-- Isolation levels
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;     -- default in most DBs
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;       -- strictest

-- Indexes
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_posts_created ON posts(created_at DESC);
CREATE INDEX idx_partial ON users(email) WHERE is_active = TRUE;  -- partial
CREATE INDEX idx_composite ON orders(customer_id, created_at);
CREATE INDEX idx_expression ON users(LOWER(email));

-- Check query plan
EXPLAIN SELECT * FROM users WHERE email = 'alice@example.com';
EXPLAIN ANALYZE SELECT * FROM users WHERE email = 'alice@example.com';

-- Views
CREATE VIEW active_users AS
    SELECT id, username, email FROM users WHERE is_active = TRUE;

-- Materialized view (cached, needs refresh)
CREATE MATERIALIZED VIEW user_stats AS
    SELECT u.id, u.username, COUNT(p.id) AS post_count
    FROM users u LEFT JOIN posts p ON p.user_id = u.id
    GROUP BY u.id, u.username;

REFRESH MATERIALIZED VIEW user_stats;
