-- Stored function (PostgreSQL PL/pgSQL)
CREATE OR REPLACE FUNCTION get_user_posts(p_user_id INT)
RETURNS TABLE(post_id INT, title VARCHAR, created_at TIMESTAMP) AS $$
BEGIN
    RETURN QUERY
    SELECT id, title, created_at
    FROM posts
    WHERE posts.user_id = p_user_id AND published = TRUE
    ORDER BY created_at DESC;
END;
$$ LANGUAGE plpgsql;

-- Call it
SELECT * FROM get_user_posts(5);

-- Function with exception handling
CREATE OR REPLACE FUNCTION safe_divide(a FLOAT, b FLOAT)
RETURNS FLOAT AS $$
BEGIN
    IF b = 0 THEN
        RAISE EXCEPTION 'Division by zero';
    END IF;
    RETURN a / b;
EXCEPTION
    WHEN division_by_zero THEN
        RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- Trigger function
CREATE OR REPLACE FUNCTION update_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER users_update_timestamp
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION update_timestamp();

-- Simple SQL function
CREATE OR REPLACE FUNCTION user_full_name(first_name TEXT, last_name TEXT)
RETURNS TEXT AS $$
    SELECT first_name || ' ' || last_name;
$$ LANGUAGE sql IMMUTABLE;
